-- OH-3: Joyce Beatty (D) won primary (79.4%), R nominee is C. Dulaney
UPDATE house_races SET candidate1_name = 'Joyce Beatty', candidate1_party = 'D', candidate2_name = 'C. Dulaney', candidate2_party = 'R'
WHERE state_code = 'OH' AND district = '3';

-- OH-5: B. Shaver won D primary (28.7% plurality), R nominee is B. Latta
UPDATE house_races SET candidate1_name = 'Brian Shaver', candidate1_party = 'D', candidate2_name = 'Bob Latta', candidate2_party = 'R'
WHERE state_code = 'OH' AND district = '5';

-- OH-7: B. Poindexter won D primary (37% plurality), R nominee is M. Miller
UPDATE house_races SET candidate1_name = 'Brian Poindexter', candidate1_party = 'D', candidate2_name = 'Max Miller', candidate2_party = 'R'
WHERE state_code = 'OH' AND district = '7';

-- OH-8: V. Enoch won D primary (74.5%), R nominee is W. Davidson
UPDATE house_races SET candidate1_name = 'Vanessa Enoch', candidate1_party = 'D', candidate2_name = 'Warren Davidson', candidate2_party = 'R'
WHERE state_code = 'OH' AND district = '8';

-- OH-10: K. Knickerbocker won D primary (32.7% plurality), R nominee is M. Turner
UPDATE house_races SET candidate1_name = 'Kristina Knickerbocker', candidate1_party = 'D', candidate2_name = 'Mike Turner', candidate2_party = 'R'
WHERE state_code = 'OH' AND district = '10';

-- OH-15: Need to check - D vs D error, need R nominee
-- OH-15 R nominee is not in the NBC results shown above, let's check

SELECT state_code, district, status, candidate1_name, candidate1_party, candidate2_name, candidate2_party 
FROM house_races WHERE state_code = 'OH' AND district IN ('3','5','7','8','10','15') ORDER BY CAST(district AS UNSIGNED);

